use crate::backend::telemetry::EnglishVocabItem;

pub struct OfflineVocabSeed {
    pub word: &'static str,
    pub phonetic: &'static str,
    pub pos: &'static str,
    pub meaning_vi: &'static str,
    pub def_en: &'static str,
    pub ex_en: &'static str,
    pub ex_vi: &'static str,
    pub topic: &'static str,
    pub level: &'static str,
    pub synonyms: &'static [&'static str],
}

impl OfflineVocabSeed {
    pub fn to_item(&self) -> EnglishVocabItem {
        EnglishVocabItem {
            word: self.word.to_string(),
            phonetic: self.phonetic.to_string(),
            part_of_speech: self.pos.to_string(),
            definition_en: self.def_en.to_string(),
            meaning_vi: self.meaning_vi.to_string(),
            example_en: self.ex_en.to_string(),
            example_vi: self.ex_vi.to_string(),
            audio_url: String::new(),
            topic: self.topic.to_string(),
            synonyms: self.synonyms.iter().map(|s| s.to_string()).collect(),
            level: self.level.to_string(),
            mastery_level: 0,
            next_review_at: 0,
            correct_count: 0,
            wrong_count: 0,
            is_starred: false,
            learned_at: 0,
        }
    }
}

